shell_commands:
node -e '
const lock = require("./package-lock.json");
for (const [k, v] of Object.entries(lock.packages)) {
  if (v.dependencies && v.dependencies.ajv) {
    console.log(k, "depends on ajv:", v.dependencies.ajv);
  }
  if (v.peerDependencies && v.peerDependencies.ajv) {
    console.log(k, "peerDepends on ajv:", v.peerDependencies.ajv);
  }
}
'

node -e '
const lock = require("./package-lock.json");
for (const [k, v] of Object.entries(lock.packages)) {
  if (v.dependencies) {
    for (const [dep, ver] of Object.entries(v.dependencies)) {
      if (dep.includes("ajv") || dep.includes("schema")) {
        console.log(k, "->", dep, ver);
      }
    }
  }
}
'
